  side?: BorderSide;
  shape?: OutlinedBorder;
  clipBehavior?: Clip;
  focusNode?: FocusNode;
  autofocus?: boolean;
  color?: WidgetStateProperty;
  backgroundColor?: Color;
  materialTapTargetSize?: MaterialTapTargetSize;
  elevation?: number;
  shadowColor?: Color;
  surfaceTintColor?: Color;
